#!/usr/bin/env python3
"""Отчёт по журналу событий."""
import argparse
import re
import sys
from collections import Counter

LINE = re.compile(r"(\d{4}-\d{2}-\d{2}) (\d{2}):(\d{2}) (\w+) (\w+) (ok|fail)")


def read_lines(path):
    with open(path, encoding="utf-8", errors="replace") as f:
        for line in f:
            yield line.rstrip("\n")


def parse(lines, bad):
    for line in lines:
        m = LINE.fullmatch(line)
        if not m:
            bad.append(line)
            continue
        day, hour, _, user, action, status = m.groups()
        yield {"day": day, "hour": hour, "user": user, "action": action, "status": status}


def analyze(records):
    by_user, fails, by_hour = Counter(), Counter(), Counter()
    total = 0
    for r in records:
        total += 1
        by_user[r["user"]] += 1
        by_hour[r["hour"]] += 1
        if r["action"] == "login" and r["status"] == "fail":
            fails[r["user"]] += 1
    return total, by_user, fails, by_hour


def main():
    parser = argparse.ArgumentParser(description="Анализ журнала")
    parser.add_argument("logfile")
    parser.add_argument("-t", "--threshold", type=int, default=3,
                        help="порог неудачных входов для предупреждения")
    args = parser.parse_args()

    bad = []
    try:
        total, by_user, fails, by_hour = analyze(parse(read_lines(args.logfile), bad))
    except FileNotFoundError:
        print(f"Нет файла {args.logfile}", file=sys.stderr)
        return 2

    print(f"Событий: {total}, не разобрано строк: {len(bad)}")
    print("\nАктивность:")
    for user, n in by_user.most_common():
        print(f"  {user:<8} {n:>5}   неудачных входов: {fails[user]}")
    if by_hour:
        hour, n = by_hour.most_common(1)[0]
        print(f"\nСамый активный час: {hour}:00 ({n} событий)")
    suspects = [u for u, n in fails.items() if n >= args.threshold]
    if suspects:
        print("\nВнимание:", ", ".join(sorted(suspects)))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

lessons.theory:
Третий проект объединяет Python и Linux: скрипт собирает показатели системы, пишет их в журнал и CSV, предупреждает о проблемах и умеет работать в цикле.

**Показатели:**

- свободное место на диске — `shutil.disk_usage`;
- память — `/proc/meminfo`;
- средняя нагрузка — `os.getloadavg()`;
- количество процессов — каталоги с числовыми именами в `/proc`.

**Важная особенность.** Система в Matrux работает в контейнере поверх Android, и часть сведений о ядре может быть закрыта. Поэтому каждый сборщик показателя обёрнут в `try/except` и возвращает `None`, если данные недоступны. Программа, которая переживает отсутствие данных, — признак профессионального кода.

**Структура:**

1. функции-сборщики, по одной на показатель;
2. `collect()` собирает всё в словарь;
3. `check()` сравнивает с порогами и возвращает список предупреждений;
4. `main()` пишет результат в CSV и журнал, при необходимости повторяет по таймеру.

Режим наблюдения завершается по Ctrl+C: исключение `KeyboardInterrupt` перехватывается, и программа выходит аккуратно.

