#!/usr/bin/env python3
"""Простой монитор системы."""
import argparse
import csv
import logging
import os
import shutil
import time
from datetime import datetime
from pathlib import Path

log = logging.getLogger("sysmon")


def disk_free_percent(path="/"):
    try:
        u = shutil.disk_usage(path)
        return round(u.free / u.total * 100, 1)
    except OSError:
        return None


def mem_available_percent():
    try:
        info = {}
        for line in Path("/proc/meminfo").read_text().splitlines():
            key, value = line.split(":")
            info[key] = int(value.split()[0])
        return round(info["MemAvailable"] / info["MemTotal"] * 100, 1)
    except (OSError, KeyError, ValueError):
        return None


def load_average():
    try:
        return round(os.getloadavg()[0], 2)
    except OSError:
        return None


def process_count():
    try:
        return sum(1 for p in Path("/proc").iterdir() if p.name.isdigit())
    except OSError:
        return None


def collect():
    return {
        "time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "disk_free": disk_free_percent(),
        "mem_free": mem_available_percent(),
        "load": load_average(),
        "procs": process_count(),
    }


def check(sample, min_disk, min_mem):
    problems = []
    if sample["disk_free"] is not None and sample["disk_free"] < min_disk:
        problems.append(f"мало места на диске: {sample['disk_free']}%")
    if sample["mem_free"] is not None and sample["mem_free"] < min_mem:
        problems.append(f"мало памяти: {sample['mem_free']}%")
    return problems


def write_csv(path, sample):
    is_new = not Path(path).exists()
    with open(path, "a", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=list(sample))
        if is_new:
            writer.writeheader()
        writer.writerow(sample)


def main():
    parser = argparse.ArgumentParser(description="Монитор системы")
    parser.add_argument("-i", "--interval", type=int, default=0,
                        help="повторять каждые N секунд (0 — один раз)")
    parser.add_argument("-o", "--output", default="sysmon.csv")
    parser.add_argument("--min-disk", type=float, default=10)
    parser.add_argument("--min-mem", type=float, default=10)
    args = parser.parse_args()

    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

    try:
        while True:
            sample = collect()
            write_csv(args.output, sample)
            shown = ", ".join(f"{k}={'н/д' if v is None else v}" for k, v in sample.items() if k != "time")
            log.info(shown)
            for problem in check(sample, args.min_disk, args.min_mem):
                log.warning(problem)
            if args.interval <= 0:
                break
            time.sleep(args.interval)
    except KeyboardInterrupt:
        log.info("Остановлено пользователем")


if __name__ == "__main__":
    main()

